import{d as u,C as t,o as c,c as b,j as a,a as r,E as o,a3 as g}from"./chunks/framework.Q4yG9rk_.js";const _=JSON.parse('{"title":"道德经第七十六章","description":"从生死的柔硬对照读兵强、木强与上下之象，保留共字歧解。","frontmatter":{"title":"道德经第七十六章","description":"从生死的柔硬对照读兵强、木强与上下之象，保留共字歧解。","category":"guide","aliases":["道德经第七十六章","老子第七十六章","dao de jing chapter 76"],"source":["王弼《道德真经注》卷四"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-76.md","filePath":"daoism/dao-de-jing/chapter-76.md","lastUpdated":1794189804000}'),p={name:"daoism/dao-de-jing/chapter-76.md"},k=u({...p,setup(m){const i=[{id:"living-body-and-rigidity",label:"人之生也柔弱",showLabel:!0,sentences:[["人之生也",{text:"柔弱",glossary:"rouruo"},"，其死也",{text:"坚强",glossary:"jianqiang-rigid"},"。"]],note:["【白话】人活着时身体柔软，死后便趋于僵硬。本章从这组生死形象起笔，借柔软、坚硬区分生命的活动与凝滞。","【读法】这是古代以生死状态立论的取象，不能当作判断个人健康、生死的医学标准；坚强也不取现代褒义的意志坚定。"]},{id:"plants-and-dryness",label:"草木之生也柔脆",showLabel:!0,sentences:[["草木之生也",{text:"柔脆",glossary:"roucui"},"，其死也",{text:"枯槁",glossary:"kugao"},"。"]],note:["【白话】草木生长时柔嫩而脆，死亡后便枯干。第二组对照把前面人的生死，推广为草木生长与枯败的形象。","【读法】本站作草木，所据录文作万物草木；保留本站字面，不静默增字。柔脆仍连生机读，不把易碎本身当作优点。"]},{id:"kinds-of-life-and-death",label:"故坚强者死之徒",showLabel:!0,sentences:[["故",{text:"坚强",glossary:"jianqiang-rigid"},"者死之",{text:"徒",glossary:"tu-kind"},"，",{text:"柔弱",glossary:"rouruo"},"者生之",{text:"徒",glossary:"tu-kind"},"。"]],note:["【白话】所以，僵硬强固的一面归于死亡这一类，柔软柔活的一面归于生命这一类。徒指类属，承接前两组取象作出判断。","【读法】读的是何种状态有利于保持生机，不是给现实中所有强者、弱者作命运判决。"]},{id:"violent-military-strength",label:"是以兵强则不胜",showLabel:!0,sentences:[["是以",{text:"兵",glossary:"bing-weapon"},"强则不胜，"]],note:["【白话】因此，依仗强兵向天下施暴，反而不能获胜。这里从生死取象转到用兵，白话依王注补明所批评的用兵方式。","【王弼注择要】「强兵以暴于天下者，物之所恶也，故必不得胜。」","【读法】注中有暴于天下与物之所恶两个条件，不应删去后改成一切兵力强大都会失败。"]},{id:"strong-wood-and-external-burden",label:"木强则共",showLabel:!0,sentences:[["木强则共。"]],note:["【白话】树木强硬，便承受外物加在其上。本句暂依王注作解释性转述；共的确切训释仍存疑。","【王弼注择要】本句下注「物所加也」。","【读法】汉典共条列有通拱、环抱等义，但仅凭字典与此处短注，仍不足以确定本句的音义。本页保留共字与问题，暂不定注音，不把解释性转述冒作已经校定的字义。"]},{id:"root-and-branches",label:"强大处下",showLabel:!0,sentences:[["强大处下，",{text:"柔弱",glossary:"rouruo"},"处上。"]],note:["【白话】强大粗壮的处在下面，柔弱细嫩的处在上面。依王注，前者是树根树本，后者是枝条的位置。","【王弼注择要】强大处下注「木之本也」，柔弱处上注「枝条是也」。","【读法】先保留树木上下的具体形象，再体会守柔的倾向。不能由此直接推出社会中的弱者一定居上、强者必然受压。"]}],n=[{id:"rouruo",term:"柔弱",sense:2},{id:"jianqiang-rigid",term:"坚强",sense:1},{id:"roucui",term:"柔脆",sense:1},{id:"kugao",term:"枯槁",sense:1},{id:"tu-kind",term:"徒",sense:1},{id:"bing-weapon",term:"兵",sense:2}];return(x,e)=>{const s=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return c(),b("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第七十六章",tabindex:"-1"},[r("道德经第七十六章 "),a("a",{class:"header-anchor",href:"#道德经第七十六章","aria-label":'Permalink to "道德经第七十六章"'},"​")],-1)),o(s,{title:"柔弱与坚强，为什么放在生死之间看",summary:"本章先以人、草木的生死对照柔软与僵硬，再转向用兵、树木与上下位置。王注把兵强限定为暴于天下，把处下、处上落实为树本与枝条。读时须分辨取象、治理告诫和疑难字，不能把柔弱直接当成万能胜法。",points:[{label:"先读",text:"从人体与草木两组对照，看柔弱在本章先指什么。"},{label:"再辨",text:"兵强依王注连施暴读，木强则共的字义保留存疑。"},{label:"后看",text:"处下、处上先看树本与枝条，再考虑怎样与行动相参。"}],hint:"柔脆读 róu cuì，枯槁读 kū gǎo，徒是一类。坚强此处偏向僵硬，不是赞美意志坚定；共字暂不定音义。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段释义",tabindex:"-1"},[r("【原典层】原文与段释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段释义","aria-label":'Permalink to "【原典层】原文与段释义"'},"​")],-1)),o(l,{sections:i,glossary:n}),e[2]||(e[2]=a("h2",{id:"【原典层】核心句引读",tabindex:"-1"},[r("【原典层】核心句引读 "),a("a",{class:"header-anchor",href:"#【原典层】核心句引读","aria-label":'Permalink to "【原典层】核心句引读"'},"​")],-1)),o(d,{lines:[{text:"人之生也柔弱，其死也坚强。",tone:"先辨生死状态",guide:"柔弱与坚强先是身体取象，勿先套进性格评价。"},{text:"是以兵强则不胜，木强则共。",tone:"转到用兵与树木",guide:"王注限定强兵施暴；共字未定，不假装全句毫无疑难。"},{text:"强大处下，柔弱处上。",tone:"落回树本枝条",guide:"先看具体上下，再思考守柔与强争。"}]}),e[3]||(e[3]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[r("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),o(h,{items:n}),e[4]||(e[4]=g("",15))])}}});export{_ as __pageData,k as default};
